import csv
ts_id = "1bfb5858-50ad-5299-b60a-f9890b9316fb"
count = 0
total = 0
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        if row["timeseries_id"] != ts_id:
            continue
        if not row["timestamp"].startswith("2018-04-21"):
            continue
        hour = int(row["timestamp"][11:13])
        # outside 08:00-18:00: before 08:00 OR after 18:00
        if hour < 8 or hour >= 19:
            try:
                v = float(row["value"])
            except:
                continue
            if v > 0:
                count += 1
        total += 1
print("count:", count, "total rows that day:", total)
